window.MG_LAZY_DATA["data/lazy/courses/a030-cbaa7c46d35d3b2f.json"]={sha256:"cbaa7c46d35d3b2fc64553b65bd3e91e53c7c0ad98a8e7c20f05e3dd36ae7311",value:{"id":"a030","title":"自我對準接觸孔製程","titleEn":"Self-aligned contact processing","category":"semiconductor","kind":"course","summary":"以 4 階段、24 個工程工作包拆解套刻容忍、間隔保護及接觸導通，完成圖解、對照、敏感度分析、故障判別、量測規劃與驗收。","summaryEn":"Four stages and 24 work packages explore overlay tolerance, spacer protection and contact continuity through diagrams, comparisons, sensitivity studies, fault diagnosis, measurement plans and acceptance reviews.","sourceIds":["v8a-ale","v8a-selective","v8a-sparc","v10-video-bf0998107592"],"status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":720,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"scope":"依公開原理編寫的雙語概念實作課；每步交付可審查的工程證據。24 步是學習拆解，不代表晶圓廠的完整配方。自行設定的數值須標為假設。題目不含可直接操作的化學混配、設備設定或量產公差；照片與外部影片為代表媒體，不是假稱每步實拍。","scopeEn":"Bilingual conceptual exercises based on public principles, with reviewable evidence at each step. The 24 steps are a learning decomposition, not a complete fab recipe. Chosen numerical inputs must be labeled hypothetical. No directly operable chemical mixtures, equipment settings or production tolerances are supplied. Photos and external videos are representative media, not claimed as recordings of every step.","diagram":{"type":"wafer","labels":["接觸與套刻","選擇性蝕刻","清潔及填充","電性與缺陷"],"labelsEn":["Contacts and overlay","Selective etching","Cleaning and fill","Electrical behavior and defects"],"original":true,"notToScale":true},"stages":[{"id":"a030-stage01","order":1,"title":"接觸與套刻","titleEn":"Contacts and overlay","description":"在「接觸與套刻」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for contacts and overlay, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a030-v8-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":[],"title":"自對準的含義","titleEn":"Define self-alignment","objective":"完成「自對準的含義」的因果圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for define self-alignment, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：自對準的含義。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：自對準利用材料或結構邊界而非完全取消套刻。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Define self-alignment. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Self-alignment uses material or structural boundaries rather than eliminating overlay. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「自對準利用材料或結構邊界而非完全取消套刻。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Self-alignment uses material or structural boundaries rather than eliminating overlay. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：沉積循環數總能從第一循環精確線性外推。 應回到「自對準的含義」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Thickness always extrapolates linearly from the first cycle. Revisit assumptions and sampling for define self-alignment and add discriminating evidence.","check":"交付「自對準的含義」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for define self-alignment: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a030-v8-01-k1","title":"自對準的含義的原理","titleEn":"Define self-alignment principle","text":"自對準利用材料或結構邊界而非完全取消套刻。","textEn":"Self-alignment uses material or structural boundaries rather than eliminating overlay."},{"id":"a030-v8-01-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","textEn":"Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}],"quiz":{"question":"評估「自對準的含義」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating define self-alignment?","options":["自對準利用材料或結構邊界而非完全取消套刻。","沉積循環數總能從第一循環精確線性外推。","厚度相同就代表介面電性相同。"],"optionsEn":["Self-alignment uses material or structural boundaries rather than eliminating overlay.","Thickness always extrapolates linearly from the first cycle.","Equal thickness implies equal interface electrical quality."],"answer":0,"explanation":"自對準利用材料或結構邊界而非完全取消套刻。 自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","explanationEn":"Self-alignment uses material or structural boundaries rather than eliminating overlay. Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}},{"id":"a030-v8-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-01"],"title":"接觸目標區","titleEn":"Mark contact targets","objective":"完成「接觸目標區」的對照表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for mark contact targets, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：接觸目標區。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：接觸需連到源汲極且避開閘金屬。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Mark contact targets. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Contacts must reach source-drain while avoiding gate metal. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「接觸需連到源汲極且避開閘金屬。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Contacts must reach source-drain while avoiding gate metal. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：沉積循環數總能從第一循環精確線性外推。 應回到「接觸目標區」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Thickness always extrapolates linearly from the first cycle. Revisit assumptions and sampling for mark contact targets and add discriminating evidence.","check":"交付「接觸目標區」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for mark contact targets: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a030-v8-02-k1","title":"接觸目標區的原理","titleEn":"Mark contact targets principle","text":"接觸需連到源汲極且避開閘金屬。","textEn":"Contacts must reach source-drain while avoiding gate metal."},{"id":"a030-v8-02-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","textEn":"Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}],"quiz":{"question":"評估「接觸目標區」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating mark contact targets?","options":["沉積循環數總能從第一循環精確線性外推。","接觸需連到源汲極且避開閘金屬。","厚度相同就代表介面電性相同。"],"optionsEn":["Thickness always extrapolates linearly from the first cycle.","Contacts must reach source-drain while avoiding gate metal.","Equal thickness implies equal interface electrical quality."],"answer":1,"explanation":"接觸需連到源汲極且避開閘金屬。 自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","explanationEn":"Contacts must reach source-drain while avoiding gate metal. Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}},{"id":"a030-v8-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-02"],"title":"閘帽與間隔層","titleEn":"Assign caps and spacers","objective":"完成「閘帽與間隔層」的敏感度草圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assign caps and spacers, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：閘帽與間隔層。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：閘帽與間隔層共同提供蝕刻保護。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assign caps and spacers. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Gate caps and spacers jointly provide etch protection. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「閘帽與間隔層共同提供蝕刻保護。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Gate caps and spacers jointly provide etch protection. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：沉積循環數總能從第一循環精確線性外推。 應回到「閘帽與間隔層」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Thickness always extrapolates linearly from the first cycle. Revisit assumptions and sampling for assign caps and spacers and add discriminating evidence.","check":"交付「閘帽與間隔層」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assign caps and spacers: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a030-v8-03-k1","title":"閘帽與間隔層的原理","titleEn":"Assign caps and spacers principle","text":"閘帽與間隔層共同提供蝕刻保護。","textEn":"Gate caps and spacers jointly provide etch protection."},{"id":"a030-v8-03-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","textEn":"Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}],"quiz":{"question":"評估「閘帽與間隔層」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assign caps and spacers?","options":["沉積循環數總能從第一循環精確線性外推。","厚度相同就代表介面電性相同。","閘帽與間隔層共同提供蝕刻保護。"],"optionsEn":["Thickness always extrapolates linearly from the first cycle.","Equal thickness implies equal interface electrical quality.","Gate caps and spacers jointly provide etch protection."],"answer":2,"explanation":"閘帽與間隔層共同提供蝕刻保護。 自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","explanationEn":"Gate caps and spacers jointly provide etch protection. Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}},{"id":"a030-v8-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-03"],"title":"套刻容忍圖","titleEn":"Draw overlay-tolerance maps","objective":"完成「套刻容忍圖」的故障判別表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for draw overlay-tolerance maps, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：套刻容忍圖。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：幾何容忍需同時計入孔寬與保護層剩餘量。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。 自訂一維落點：目標區寬 40、孔寬 20 單位；先求完全落入的中心偏移上限，再討論為何選擇性保護只能改變部分失效邊界。","instructionEn":"Question for this step: Draw overlay-tolerance maps. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Tolerance includes opening width and remaining protective material. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs. Hypothetical 1D landing: target width 40 and opening width 20 units. Find the center-offset limit for full landing, then explain why selective protection changes only some failure boundaries.","observation":"檢查結果是否能支持「幾何容忍需同時計入孔寬與保護層剩餘量。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Tolerance includes opening width and remaining protective material. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：沉積循環數總能從第一循環精確線性外推。 應回到「套刻容忍圖」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Thickness always extrapolates linearly from the first cycle. Revisit assumptions and sampling for draw overlay-tolerance maps and add discriminating evidence.","check":"交付「套刻容忍圖」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。 同時交付算例的中間步驟或比較圖，並標示假設與模型限制。","checkEn":"Submit the fault-discrimination table for draw overlay-tolerance maps: List two hypotheses, discriminating evidence for each and a check order. Also submit intermediate calculations or comparison diagrams with assumptions and model limits.","knowledge":[{"id":"a030-v8-04-k1","title":"套刻容忍圖的原理","titleEn":"Draw overlay-tolerance maps principle","text":"幾何容忍需同時計入孔寬與保護層剩餘量。","textEn":"Tolerance includes opening width and remaining protective material."},{"id":"a030-v8-04-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","textEn":"Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}],"quiz":{"question":"評估「套刻容忍圖」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating draw overlay-tolerance maps?","options":["幾何容忍需同時計入孔寬與保護層剩餘量。","沉積循環數總能從第一循環精確線性外推。","厚度相同就代表介面電性相同。"],"optionsEn":["Tolerance includes opening width and remaining protective material.","Thickness always extrapolates linearly from the first cycle.","Equal thickness implies equal interface electrical quality."],"answer":0,"explanation":"幾何容忍需同時計入孔寬與保護層剩餘量。 自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","explanationEn":"Tolerance includes opening width and remaining protective material. Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}},{"id":"a030-v8-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-04"],"title":"縱橫比","titleEn":"Assess aspect ratio","objective":"完成「縱橫比」的量測規劃，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for assess aspect ratio, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：縱橫比。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：深窄孔的傳輸與底部去除不同於平面。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess aspect ratio. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Transport and bottom removal in deep holes differ from planar surfaces. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「深窄孔的傳輸與底部去除不同於平面。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Transport and bottom removal in deep holes differ from planar surfaces. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：沉積循環數總能從第一循環精確線性外推。 應回到「縱橫比」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Thickness always extrapolates linearly from the first cycle. Revisit assumptions and sampling for assess aspect ratio and add discriminating evidence.","check":"交付「縱橫比」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for assess aspect ratio: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a030-v8-05-k1","title":"縱橫比的原理","titleEn":"Assess aspect ratio principle","text":"深窄孔的傳輸與底部去除不同於平面。","textEn":"Transport and bottom removal in deep holes differ from planar surfaces."},{"id":"a030-v8-05-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","textEn":"Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}],"quiz":{"question":"評估「縱橫比」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess aspect ratio?","options":["沉積循環數總能從第一循環精確線性外推。","深窄孔的傳輸與底部去除不同於平面。","厚度相同就代表介面電性相同。"],"optionsEn":["Thickness always extrapolates linearly from the first cycle.","Transport and bottom removal in deep holes differ from planar surfaces.","Equal thickness implies equal interface electrical quality."],"answer":1,"explanation":"深窄孔的傳輸與底部去除不同於平面。 自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","explanationEn":"Transport and bottom removal in deep holes differ from planar surfaces. Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}},{"id":"a030-v8-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-05"],"title":"材料選擇比","titleEn":"Define material selectivity","objective":"完成「材料選擇比」的工程驗收單，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for define material selectivity, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：材料選擇比。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：高選擇比仍需知道保護層可接受損失。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Define material selectivity. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: High selectivity still requires an allowable protection-layer loss. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高選擇比仍需知道保護層可接受損失。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: High selectivity still requires an allowable protection-layer loss. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：沉積循環數總能從第一循環精確線性外推。 應回到「材料選擇比」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Thickness always extrapolates linearly from the first cycle. Revisit assumptions and sampling for define material selectivity and add discriminating evidence.","check":"交付「材料選擇比」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for define material selectivity: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a030-v8-06-k1","title":"材料選擇比的原理","titleEn":"Define material selectivity principle","text":"高選擇比仍需知道保護層可接受損失。","textEn":"High selectivity still requires an allowable protection-layer loss."},{"id":"a030-v8-06-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","textEn":"Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}],"quiz":{"question":"評估「材料選擇比」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating define material selectivity?","options":["沉積循環數總能從第一循環精確線性外推。","厚度相同就代表介面電性相同。","高選擇比仍需知道保護層可接受損失。"],"optionsEn":["Thickness always extrapolates linearly from the first cycle.","Equal thickness implies equal interface electrical quality.","High selectivity still requires an allowable protection-layer loss."],"answer":2,"explanation":"高選擇比仍需知道保護層可接受損失。 自對準保護來自材料選擇性及結構重疊，套刻偏移仍可能縮小落點或增加角落暴露。","explanationEn":"High selectivity still requires an allowable protection-layer loss. Self-alignment relies on material selectivity and overlap; overlay shifts can still reduce landing area or expose corners."}}]},{"id":"a030-stage02","order":2,"title":"選擇性蝕刻","titleEn":"Selective etching","description":"在「選擇性蝕刻」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for selective etching, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a030-v8-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-06"],"title":"離子方向性","titleEn":"Assess ion directionality","objective":"完成「離子方向性」的因果圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for assess ion directionality, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：離子方向性。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：方向性有助向下去除但仍可能傷害角落。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess ion directionality. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Directionality helps downward removal but can still damage corners. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「方向性有助向下去除但仍可能傷害角落。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Directionality helps downward removal but can still damage corners. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：入口飽和就證明深槽底部已飽和。 應回到「離子方向性」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Entrance saturation proves deep-feature bottom saturation. Revisit assumptions and sampling for assess ion directionality and add discriminating evidence.","check":"交付「離子方向性」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for assess ion directionality: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a030-v8-07-k1","title":"離子方向性的原理","titleEn":"Assess ion directionality principle","text":"方向性有助向下去除但仍可能傷害角落。","textEn":"Directionality helps downward removal but can still damage corners."},{"id":"a030-v8-07-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","textEn":"Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}],"quiz":{"question":"評估「離子方向性」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess ion directionality?","options":["方向性有助向下去除但仍可能傷害角落。","入口飽和就證明深槽底部已飽和。","平均成分足以排除局部相分離。"],"optionsEn":["Directionality helps downward removal but can still damage corners.","Entrance saturation proves deep-feature bottom saturation.","Mean composition rules out local phase separation."],"answer":0,"explanation":"方向性有助向下去除但仍可能傷害角落。 方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","explanationEn":"Directionality helps downward removal but can still damage corners. Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}},{"id":"a030-v8-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-07"],"title":"原子層蝕刻循環","titleEn":"Decompose an ALE cycle","objective":"完成「原子層蝕刻循環」的對照表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for decompose an ale cycle, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：原子層蝕刻循環。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：表面改質與移除需作為分開的作用理解。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Decompose an ALE cycle. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Surface modification and removal are distinct operations. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「表面改質與移除需作為分開的作用理解。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Surface modification and removal are distinct operations. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：入口飽和就證明深槽底部已飽和。 應回到「原子層蝕刻循環」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Entrance saturation proves deep-feature bottom saturation. Revisit assumptions and sampling for decompose an ale cycle and add discriminating evidence.","check":"交付「原子層蝕刻循環」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for decompose an ale cycle: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a030-v8-08-k1","title":"原子層蝕刻循環的原理","titleEn":"Decompose an ALE cycle principle","text":"表面改質與移除需作為分開的作用理解。","textEn":"Surface modification and removal are distinct operations."},{"id":"a030-v8-08-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","textEn":"Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}],"quiz":{"question":"評估「原子層蝕刻循環」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating decompose an ale cycle?","options":["入口飽和就證明深槽底部已飽和。","表面改質與移除需作為分開的作用理解。","平均成分足以排除局部相分離。"],"optionsEn":["Entrance saturation proves deep-feature bottom saturation.","Surface modification and removal are distinct operations.","Mean composition rules out local phase separation."],"answer":1,"explanation":"表面改質與移除需作為分開的作用理解。 方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","explanationEn":"Surface modification and removal are distinct operations. Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}},{"id":"a030-v8-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-08"],"title":"底部殘留","titleEn":"Inspect bottom residue","objective":"完成「底部殘留」的敏感度草圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for inspect bottom residue, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：底部殘留。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：孔已打開不代表接觸界面完全清潔。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Inspect bottom residue. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: An open hole does not prove a clean contact interface. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「孔已打開不代表接觸界面完全清潔。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: An open hole does not prove a clean contact interface. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：入口飽和就證明深槽底部已飽和。 應回到「底部殘留」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Entrance saturation proves deep-feature bottom saturation. Revisit assumptions and sampling for inspect bottom residue and add discriminating evidence.","check":"交付「底部殘留」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for inspect bottom residue: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a030-v8-09-k1","title":"底部殘留的原理","titleEn":"Inspect bottom residue principle","text":"孔已打開不代表接觸界面完全清潔。","textEn":"An open hole does not prove a clean contact interface."},{"id":"a030-v8-09-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","textEn":"Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}],"quiz":{"question":"評估「底部殘留」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating inspect bottom residue?","options":["入口飽和就證明深槽底部已飽和。","平均成分足以排除局部相分離。","孔已打開不代表接觸界面完全清潔。"],"optionsEn":["Entrance saturation proves deep-feature bottom saturation.","Mean composition rules out local phase separation.","An open hole does not prove a clean contact interface."],"answer":2,"explanation":"孔已打開不代表接觸界面完全清潔。 方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","explanationEn":"An open hole does not prove a clean contact interface. Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}},{"id":"a030-v8-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-09"],"title":"角落保護","titleEn":"Measure corner loss","objective":"完成「角落保護」的故障判別表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for measure corner loss, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：角落保護。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：平均間隔厚度不能代表最薄角落。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure corner loss. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Mean spacer thickness does not represent the thinnest corner. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「平均間隔厚度不能代表最薄角落。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Mean spacer thickness does not represent the thinnest corner. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：入口飽和就證明深槽底部已飽和。 應回到「角落保護」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Entrance saturation proves deep-feature bottom saturation. Revisit assumptions and sampling for measure corner loss and add discriminating evidence.","check":"交付「角落保護」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for measure corner loss: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a030-v8-10-k1","title":"角落保護的原理","titleEn":"Measure corner loss principle","text":"平均間隔厚度不能代表最薄角落。","textEn":"Mean spacer thickness does not represent the thinnest corner."},{"id":"a030-v8-10-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","textEn":"Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}],"quiz":{"question":"評估「角落保護」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure corner loss?","options":["平均間隔厚度不能代表最薄角落。","入口飽和就證明深槽底部已飽和。","平均成分足以排除局部相分離。"],"optionsEn":["Mean spacer thickness does not represent the thinnest corner.","Entrance saturation proves deep-feature bottom saturation.","Mean composition rules out local phase separation."],"answer":0,"explanation":"平均間隔厚度不能代表最薄角落。 方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","explanationEn":"Mean spacer thickness does not represent the thinnest corner. Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}},{"id":"a030-v8-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-10"],"title":"微負載","titleEn":"Compare microloading","objective":"完成「微負載」的量測規劃，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for compare microloading, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：微負載。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：不同孔密度及尺寸可能有不同清除時間。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Compare microloading. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Hole density and size can cause different clearing times. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「不同孔密度及尺寸可能有不同清除時間。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Hole density and size can cause different clearing times. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：入口飽和就證明深槽底部已飽和。 應回到「微負載」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Entrance saturation proves deep-feature bottom saturation. Revisit assumptions and sampling for compare microloading and add discriminating evidence.","check":"交付「微負載」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for compare microloading: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a030-v8-11-k1","title":"微負載的原理","titleEn":"Compare microloading principle","text":"不同孔密度及尺寸可能有不同清除時間。","textEn":"Hole density and size can cause different clearing times."},{"id":"a030-v8-11-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","textEn":"Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}],"quiz":{"question":"評估「微負載」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compare microloading?","options":["入口飽和就證明深槽底部已飽和。","不同孔密度及尺寸可能有不同清除時間。","平均成分足以排除局部相分離。"],"optionsEn":["Entrance saturation proves deep-feature bottom saturation.","Hole density and size can cause different clearing times.","Mean composition rules out local phase separation."],"answer":1,"explanation":"不同孔密度及尺寸可能有不同清除時間。 方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","explanationEn":"Hole density and size can cause different clearing times. Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}},{"id":"a030-v8-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-11"],"title":"終點與過蝕","titleEn":"Separate endpoint and overetch","objective":"完成「終點與過蝕」的工程驗收單，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for separate endpoint and overetch, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：終點與過蝕。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：最慢孔清除所需過蝕會消耗其他位置保護層。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate endpoint and overetch. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Overetch for slow holes consumes protection elsewhere. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「最慢孔清除所需過蝕會消耗其他位置保護層。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Overetch for slow holes consumes protection elsewhere. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：入口飽和就證明深槽底部已飽和。 應回到「終點與過蝕」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Entrance saturation proves deep-feature bottom saturation. Revisit assumptions and sampling for separate endpoint and overetch and add discriminating evidence.","check":"交付「終點與過蝕」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for separate endpoint and overetch: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a030-v8-12-k1","title":"終點與過蝕的原理","titleEn":"Separate endpoint and overetch principle","text":"最慢孔清除所需過蝕會消耗其他位置保護層。","textEn":"Overetch for slow holes consumes protection elsewhere."},{"id":"a030-v8-12-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","textEn":"Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}],"quiz":{"question":"評估「終點與過蝕」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate endpoint and overetch?","options":["入口飽和就證明深槽底部已飽和。","平均成分足以排除局部相分離。","最慢孔清除所需過蝕會消耗其他位置保護層。"],"optionsEn":["Entrance saturation proves deep-feature bottom saturation.","Mean composition rules out local phase separation.","Overetch for slow holes consumes protection elsewhere."],"answer":2,"explanation":"最慢孔清除所需過蝕會消耗其他位置保護層。 方向性蝕刻控制形狀，材料選擇性控制保護層損失，兩種能力需要分開量化。","explanationEn":"Overetch for slow holes consumes protection elsewhere. Directional etching controls shape while selectivity controls protective-layer loss; quantify these capabilities separately."}}]},{"id":"a030-stage03","order":3,"title":"清潔及填充","titleEn":"Cleaning and fill","description":"在「清潔及填充」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for cleaning and fill, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a030-v8-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-12"],"title":"蝕刻後殘留","titleEn":"Classify post-etch residues","objective":"完成「蝕刻後殘留」的因果圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for classify post-etch residues, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：蝕刻後殘留。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：聚合物與金屬殘留可能需要不同判讀。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Classify post-etch residues. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Polymer and metal residues need different interpretation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「聚合物與金屬殘留可能需要不同判讀。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Polymer and metal residues need different interpretation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：高介電常數保證沒有漏電及陷阱。 應回到「蝕刻後殘留」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: High permittivity guarantees no leakage or traps. Revisit assumptions and sampling for classify post-etch residues and add discriminating evidence.","check":"交付「蝕刻後殘留」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for classify post-etch residues: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a030-v8-13-k1","title":"蝕刻後殘留的原理","titleEn":"Classify post-etch residues principle","text":"聚合物與金屬殘留可能需要不同判讀。","textEn":"Polymer and metal residues need different interpretation."},{"id":"a030-v8-13-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","textEn":"Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}],"quiz":{"question":"評估「蝕刻後殘留」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating classify post-etch residues?","options":["聚合物與金屬殘留可能需要不同判讀。","高介電常數保證沒有漏電及陷阱。","去除上層材料不需檢查下層損失。"],"optionsEn":["Polymer and metal residues need different interpretation.","High permittivity guarantees no leakage or traps.","Removing an upper layer needs no lower-layer loss check."],"answer":0,"explanation":"聚合物與金屬殘留可能需要不同判讀。 接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","explanationEn":"Polymer and metal residues need different interpretation. Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}},{"id":"a030-v8-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-13"],"title":"源汲極損失","titleEn":"Measure source-drain loss","objective":"完成「源汲極損失」的對照表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for measure source-drain loss, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：源汲極損失。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：底部清潔不能以過度消耗目標材料為代價。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure source-drain loss. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Bottom cleaning must not excessively consume target material. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「底部清潔不能以過度消耗目標材料為代價。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Bottom cleaning must not excessively consume target material. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：高介電常數保證沒有漏電及陷阱。 應回到「源汲極損失」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: High permittivity guarantees no leakage or traps. Revisit assumptions and sampling for measure source-drain loss and add discriminating evidence.","check":"交付「源汲極損失」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for measure source-drain loss: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a030-v8-14-k1","title":"源汲極損失的原理","titleEn":"Measure source-drain loss principle","text":"底部清潔不能以過度消耗目標材料為代價。","textEn":"Bottom cleaning must not excessively consume target material."},{"id":"a030-v8-14-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","textEn":"Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}],"quiz":{"question":"評估「源汲極損失」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure source-drain loss?","options":["高介電常數保證沒有漏電及陷阱。","底部清潔不能以過度消耗目標材料為代價。","去除上層材料不需檢查下層損失。"],"optionsEn":["High permittivity guarantees no leakage or traps.","Bottom cleaning must not excessively consume target material.","Removing an upper layer needs no lower-layer loss check."],"answer":1,"explanation":"底部清潔不能以過度消耗目標材料為代價。 接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","explanationEn":"Bottom cleaning must not excessively consume target material. Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}},{"id":"a030-v8-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-14"],"title":"襯層厚度預算","titleEn":"Budget liner thickness","objective":"完成「襯層厚度預算」的敏感度草圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for budget liner thickness, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：襯層厚度預算。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：襯層會消耗孔內可用導體截面。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Budget liner thickness. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Liners consume available conductor cross-section. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「襯層會消耗孔內可用導體截面。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Liners consume available conductor cross-section. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：高介電常數保證沒有漏電及陷阱。 應回到「襯層厚度預算」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: High permittivity guarantees no leakage or traps. Revisit assumptions and sampling for budget liner thickness and add discriminating evidence.","check":"交付「襯層厚度預算」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for budget liner thickness: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a030-v8-15-k1","title":"襯層厚度預算的原理","titleEn":"Budget liner thickness principle","text":"襯層會消耗孔內可用導體截面。","textEn":"Liners consume available conductor cross-section."},{"id":"a030-v8-15-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","textEn":"Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}],"quiz":{"question":"評估「襯層厚度預算」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating budget liner thickness?","options":["高介電常數保證沒有漏電及陷阱。","去除上層材料不需檢查下層損失。","襯層會消耗孔內可用導體截面。"],"optionsEn":["High permittivity guarantees no leakage or traps.","Removing an upper layer needs no lower-layer loss check.","Liners consume available conductor cross-section."],"answer":2,"explanation":"襯層會消耗孔內可用導體截面。 接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","explanationEn":"Liners consume available conductor cross-section. Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}},{"id":"a030-v8-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-15"],"title":"接觸填充","titleEn":"Inspect contact fill","objective":"完成「接觸填充」的故障判別表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for inspect contact fill, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：接觸填充。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：早期封口可留下中空接觸。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Inspect contact fill. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Premature closure can leave hollow contacts. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「早期封口可留下中空接觸。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Premature closure can leave hollow contacts. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：高介電常數保證沒有漏電及陷阱。 應回到「接觸填充」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: High permittivity guarantees no leakage or traps. Revisit assumptions and sampling for inspect contact fill and add discriminating evidence.","check":"交付「接觸填充」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for inspect contact fill: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a030-v8-16-k1","title":"接觸填充的原理","titleEn":"Inspect contact fill principle","text":"早期封口可留下中空接觸。","textEn":"Premature closure can leave hollow contacts."},{"id":"a030-v8-16-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","textEn":"Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}],"quiz":{"question":"評估「接觸填充」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating inspect contact fill?","options":["早期封口可留下中空接觸。","高介電常數保證沒有漏電及陷阱。","去除上層材料不需檢查下層損失。"],"optionsEn":["Premature closure can leave hollow contacts.","High permittivity guarantees no leakage or traps.","Removing an upper layer needs no lower-layer loss check."],"answer":0,"explanation":"早期封口可留下中空接觸。 接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","explanationEn":"Premature closure can leave hollow contacts. Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}},{"id":"a030-v8-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-16"],"title":"平坦化隔離","titleEn":"Assess planarization isolation","objective":"完成「平坦化隔離」的量測規劃，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for assess planarization isolation, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：平坦化隔離。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：表面殘金屬可能連接原本分開的接觸。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess planarization isolation. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Residual surface metal can bridge separate contacts. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「表面殘金屬可能連接原本分開的接觸。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Residual surface metal can bridge separate contacts. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：高介電常數保證沒有漏電及陷阱。 應回到「平坦化隔離」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: High permittivity guarantees no leakage or traps. Revisit assumptions and sampling for assess planarization isolation and add discriminating evidence.","check":"交付「平坦化隔離」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for assess planarization isolation: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a030-v8-17-k1","title":"平坦化隔離的原理","titleEn":"Assess planarization isolation principle","text":"表面殘金屬可能連接原本分開的接觸。","textEn":"Residual surface metal can bridge separate contacts."},{"id":"a030-v8-17-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","textEn":"Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}],"quiz":{"question":"評估「平坦化隔離」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess planarization isolation?","options":["高介電常數保證沒有漏電及陷阱。","表面殘金屬可能連接原本分開的接觸。","去除上層材料不需檢查下層損失。"],"optionsEn":["High permittivity guarantees no leakage or traps.","Residual surface metal can bridge separate contacts.","Removing an upper layer needs no lower-layer loss check."],"answer":1,"explanation":"表面殘金屬可能連接原本分開的接觸。 接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","explanationEn":"Residual surface metal can bridge separate contacts. Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}},{"id":"a030-v8-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-17"],"title":"阻障完整性","titleEn":"Assess barrier continuity","objective":"完成「阻障完整性」的工程驗收單，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for assess barrier continuity, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：阻障完整性。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：低電阻填充仍需防止材料向鄰近區擴散。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess barrier continuity. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Low-resistance fill still needs diffusion containment. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「低電阻填充仍需防止材料向鄰近區擴散。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Low-resistance fill still needs diffusion containment. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：高介電常數保證沒有漏電及陷阱。 應回到「阻障完整性」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: High permittivity guarantees no leakage or traps. Revisit assumptions and sampling for assess barrier continuity and add discriminating evidence.","check":"交付「阻障完整性」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for assess barrier continuity: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a030-v8-18-k1","title":"阻障完整性的原理","titleEn":"Assess barrier continuity principle","text":"低電阻填充仍需防止材料向鄰近區擴散。","textEn":"Low-resistance fill still needs diffusion containment."},{"id":"a030-v8-18-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","textEn":"Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}],"quiz":{"question":"評估「阻障完整性」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess barrier continuity?","options":["高介電常數保證沒有漏電及陷阱。","去除上層材料不需檢查下層損失。","低電阻填充仍需防止材料向鄰近區擴散。"],"optionsEn":["High permittivity guarantees no leakage or traps.","Removing an upper layer needs no lower-layer loss check.","Low-resistance fill still needs diffusion containment."],"answer":2,"explanation":"低電阻填充仍需防止材料向鄰近區擴散。 接觸襯層可保護界面卻消耗導體截面，填充完成後仍需檢查空洞與實際連通面積。","explanationEn":"Low-resistance fill still needs diffusion containment. Contact liners protect interfaces but consume conductor area; inspect voids and actual connected area after filling."}}]},{"id":"a030-stage04","order":4,"title":"電性與缺陷","titleEn":"Electrical behavior and defects","description":"在「電性與缺陷」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for electrical behavior and defects, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a030-v8-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-18"],"title":"開路與高阻","titleEn":"Separate opens and high resistance","objective":"完成「開路與高阻」的因果圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for separate opens and high resistance, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：開路與高阻。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：完全開路與部分接觸不良需要不同診斷。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate opens and high resistance. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Complete opens and partial contact failure need different diagnosis. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「完全開路與部分接觸不良需要不同診斷。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Complete opens and partial contact failure need different diagnosis. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：低塊材電阻率保證低界面接觸電阻。 應回到「開路與高阻」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Low bulk resistivity guarantees low interface contact resistance. Revisit assumptions and sampling for separate opens and high resistance and add discriminating evidence.","check":"交付「開路與高阻」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for separate opens and high resistance: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a030-v8-19-k1","title":"開路與高阻的原理","titleEn":"Separate opens and high resistance principle","text":"完全開路與部分接觸不良需要不同診斷。","textEn":"Complete opens and partial contact failure need different diagnosis."},{"id":"a030-v8-19-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","textEn":"Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}],"quiz":{"question":"評估「開路與高阻」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate opens and high resistance?","options":["完全開路與部分接觸不良需要不同診斷。","低塊材電阻率保證低界面接觸電阻。","較快成長永遠改善圖案選擇性。"],"optionsEn":["Complete opens and partial contact failure need different diagnosis.","Low bulk resistivity guarantees low interface contact resistance.","Faster growth always improves pattern selectivity."],"answer":0,"explanation":"完全開路與部分接觸不良需要不同診斷。 導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","explanationEn":"Complete opens and partial contact failure need different diagnosis. Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}},{"id":"a030-v8-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-19"],"title":"閘接觸短路","titleEn":"Test gate-contact shorts","objective":"完成「閘接觸短路」的對照表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for test gate-contact shorts, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：閘接觸短路。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：源汲極導通不代表與閘保持隔離。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Test gate-contact shorts. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Source-drain continuity does not prove gate isolation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「源汲極導通不代表與閘保持隔離。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Source-drain continuity does not prove gate isolation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：低塊材電阻率保證低界面接觸電阻。 應回到「閘接觸短路」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Low bulk resistivity guarantees low interface contact resistance. Revisit assumptions and sampling for test gate-contact shorts and add discriminating evidence.","check":"交付「閘接觸短路」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for test gate-contact shorts: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a030-v8-20-k1","title":"閘接觸短路的原理","titleEn":"Test gate-contact shorts principle","text":"源汲極導通不代表與閘保持隔離。","textEn":"Source-drain continuity does not prove gate isolation."},{"id":"a030-v8-20-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","textEn":"Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}],"quiz":{"question":"評估「閘接觸短路」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating test gate-contact shorts?","options":["低塊材電阻率保證低界面接觸電阻。","源汲極導通不代表與閘保持隔離。","較快成長永遠改善圖案選擇性。"],"optionsEn":["Low bulk resistivity guarantees low interface contact resistance.","Source-drain continuity does not prove gate isolation.","Faster growth always improves pattern selectivity."],"answer":1,"explanation":"源汲極導通不代表與閘保持隔離。 導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","explanationEn":"Source-drain continuity does not prove gate isolation. Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}},{"id":"a030-v8-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-20"],"title":"接觸鏈統計","titleEn":"Analyze contact-chain statistics","objective":"完成「接觸鏈統計」的敏感度草圖，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for analyze contact-chain statistics, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：接觸鏈統計。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：長鏈失效機率與單接點良率相關。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Analyze contact-chain statistics. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Chain failure probability depends on individual contact yield. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「長鏈失效機率與單接點良率相關。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Chain failure probability depends on individual contact yield. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：低塊材電阻率保證低界面接觸電阻。 應回到「接觸鏈統計」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Low bulk resistivity guarantees low interface contact resistance. Revisit assumptions and sampling for analyze contact-chain statistics and add discriminating evidence.","check":"交付「接觸鏈統計」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for analyze contact-chain statistics: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a030-v8-21-k1","title":"接觸鏈統計的原理","titleEn":"Analyze contact-chain statistics principle","text":"長鏈失效機率與單接點良率相關。","textEn":"Chain failure probability depends on individual contact yield."},{"id":"a030-v8-21-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","textEn":"Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}],"quiz":{"question":"評估「接觸鏈統計」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating analyze contact-chain statistics?","options":["低塊材電阻率保證低界面接觸電阻。","較快成長永遠改善圖案選擇性。","長鏈失效機率與單接點良率相關。"],"optionsEn":["Low bulk resistivity guarantees low interface contact resistance.","Faster growth always improves pattern selectivity.","Chain failure probability depends on individual contact yield."],"answer":2,"explanation":"長鏈失效機率與單接點良率相關。 導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","explanationEn":"Chain failure probability depends on individual contact yield. Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}},{"id":"a030-v8-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-21"],"title":"截面與電性對照","titleEn":"Correlate sections and electrical data","objective":"完成「截面與電性對照」的故障判別表，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for correlate sections and electrical data, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：截面與電性對照。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：截面位置需與實際失效位置匹配。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Correlate sections and electrical data. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Cross-sections must match actual electrical failure locations. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「截面位置需與實際失效位置匹配。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Cross-sections must match actual electrical failure locations. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：低塊材電阻率保證低界面接觸電阻。 應回到「截面與電性對照」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Low bulk resistivity guarantees low interface contact resistance. Revisit assumptions and sampling for correlate sections and electrical data and add discriminating evidence.","check":"交付「截面與電性對照」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for correlate sections and electrical data: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a030-v8-22-k1","title":"截面與電性對照的原理","titleEn":"Correlate sections and electrical data principle","text":"截面位置需與實際失效位置匹配。","textEn":"Cross-sections must match actual electrical failure locations."},{"id":"a030-v8-22-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","textEn":"Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}],"quiz":{"question":"評估「截面與電性對照」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating correlate sections and electrical data?","options":["截面位置需與實際失效位置匹配。","低塊材電阻率保證低界面接觸電阻。","較快成長永遠改善圖案選擇性。"],"optionsEn":["Cross-sections must match actual electrical failure locations.","Low bulk resistivity guarantees low interface contact resistance.","Faster growth always improves pattern selectivity."],"answer":0,"explanation":"截面位置需與實際失效位置匹配。 導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","explanationEn":"Cross-sections must match actual electrical failure locations. Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}},{"id":"a030-v8-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-22"],"title":"設計窗口","titleEn":"Build a design-process window","objective":"完成「設計窗口」的量測規劃，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for build a design-process window, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：設計窗口。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：孔寬、套刻及保護層損失需共同取交集。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Build a design-process window. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Opening width, overlay and protection loss define a joint window. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「孔寬、套刻及保護層損失需共同取交集。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Opening width, overlay and protection loss define a joint window. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：低塊材電阻率保證低界面接觸電阻。 應回到「設計窗口」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Low bulk resistivity guarantees low interface contact resistance. Revisit assumptions and sampling for build a design-process window and add discriminating evidence.","check":"交付「設計窗口」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for build a design-process window: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a030-v8-23-k1","title":"設計窗口的原理","titleEn":"Build a design-process window principle","text":"孔寬、套刻及保護層損失需共同取交集。","textEn":"Opening width, overlay and protection loss define a joint window."},{"id":"a030-v8-23-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","textEn":"Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}],"quiz":{"question":"評估「設計窗口」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating build a design-process window?","options":["低塊材電阻率保證低界面接觸電阻。","孔寬、套刻及保護層損失需共同取交集。","較快成長永遠改善圖案選擇性。"],"optionsEn":["Low bulk resistivity guarantees low interface contact resistance.","Opening width, overlay and protection loss define a joint window.","Faster growth always improves pattern selectivity."],"answer":1,"explanation":"孔寬、套刻及保護層損失需共同取交集。 導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","explanationEn":"Opening width, overlay and protection loss define a joint window. Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}},{"id":"a030-v8-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-ale","v8a-selective","v8a-sparc"],"prerequisiteIds":["a030-v8-23"],"title":"SAC 放行","titleEn":"Accept self-aligned contacts","objective":"完成「SAC 放行」的工程驗收單，把套刻容忍、間隔保護及接觸導通中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for accept self-aligned contacts, connecting relevant limits in overlay tolerance, spacer protection and contact continuity to observable evidence.","instruction":"本步問題：SAC 放行。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：導通、隔離、填充及套刻裕度必須一起驗證。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Accept self-aligned contacts. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Continuity, isolation, fill and overlay margin need joint validation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「導通、隔離、填充及套刻裕度必須一起驗證。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Continuity, isolation, fill and overlay margin need joint validation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：低塊材電阻率保證低界面接觸電阻。 應回到「SAC 放行」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Low bulk resistivity guarantees low interface contact resistance. Revisit assumptions and sampling for accept self-aligned contacts and add discriminating evidence.","check":"交付「SAC 放行」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for accept self-aligned contacts: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a030-v8-24-k1","title":"SAC 放行的原理","titleEn":"Accept self-aligned contacts principle","text":"導通、隔離、填充及套刻裕度必須一起驗證。","textEn":"Continuity, isolation, fill and overlay margin need joint validation."},{"id":"a030-v8-24-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","textEn":"Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}],"quiz":{"question":"評估「SAC 放行」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating accept self-aligned contacts?","options":["低塊材電阻率保證低界面接觸電阻。","較快成長永遠改善圖案選擇性。","導通、隔離、填充及套刻裕度必須一起驗證。"],"optionsEn":["Low bulk resistivity guarantees low interface contact resistance.","Faster growth always improves pattern selectivity.","Continuity, isolation, fill and overlay margin need joint validation."],"answer":2,"explanation":"導通、隔離、填充及套刻裕度必須一起驗證。 導通、閘隔離及鄰孔隔離是不同電路條件；一種接觸鏈測試不能取代所有漏電與短路檢查。","explanationEn":"Continuity, isolation, fill and overlay margin need joint validation. Continuity, gate isolation and neighbor isolation are different conditions; one chain test cannot replace all leakage and short checks."}}]}],"subcategory":"devices","subcategoryTitle":"先進電晶體","subcategoryTitleEn":"Advanced transistors"}};
